html, body { margin: 0; background: transparent; }
body { font: 15px/1.3 -apple-system, system-ui, sans-serif; color: #1c1c1e; -webkit-text-size-adjust: 100%; }
h1 { margin: 0 0 2px; font-size: 15px; font-weight: 600; }
