<h1>Weekly retention</h1><p class="sub">Users still active, by signup week</p>
<svg id="c" viewBox="0 0 340 200"></svg>
<div class="legend"><span><i style="background:#c7c7cc"></i>September</span><span><i style="background:#7c5cff"></i>October</span><span><i style="background:#ff4d8d"></i>Since 2.0</span></div>
<script>
const W = 340, H = 200, L = 36, R = 8, T = 8, B = 22;
const x = w => L + (W - L - R) * w / 7, y = v => T + (H - T - B) * (1 - v / 100);
let s = "";
for (const v of [0, 25, 50, 75, 100]) s += `<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#ececf0"/><text x="${L-6}" y="${y(v)+3.5}" font-size="10" fill="#8e8e93" text-anchor="end">${v}%</text>`;
for (let w = 0; w < 8; w++) s += `<text x="${x(w)}" y="${H-5}" font-size="10" fill="#8e8e93" text-anchor="middle">W${w}</text>`;
const line = (vals, c, wd) => `<polyline points="${vals.map((v,i)=>`${x(i)},${y(v)}`).join(" ")}" fill="none" stroke="${c}" stroke-width="${wd}" stroke-linejoin="round" stroke-linecap="round"/>`;
s += line([100,58,46,40,36,33,31,30], "#c7c7cc", 2);
s += line([100,60,48,42,38,36], "#c7c7cc", 2);
s += line([100,66,55,49], "#7c5cff", 2.5);
s += line([100,71,64], "#ff4d8d", 3);
s += `<circle cx="${x(2)}" cy="${y(64)}" r="4" fill="#ff4d8d" stroke="#fff" stroke-width="2"/><text x="${x(2)+8}" y="${y(64)-8}" font-size="11" font-weight="600" fill="#ff4d8d">64%</text>`;
document.getElementById("c").innerHTML = s;
</script></body></html>

